(()=>{window.__geo=[];const g=navigator.geolocation;const gcp=g.getCurrentPosition.bind(g);const wp=g.watchPosition.bind(g);
g.getCurrentPosition=(ok,err,o)=>{const t=Date.now();window.__geo.push('gcp '+JSON.stringify(o));return gcp(p=>{window.__geo.push('gcp ok '+(Date.now()-t));ok&&ok(p)},e=>{window.__geo.push('gcp err '+e.code+' '+e.message+' '+(Date.now()-t));err&&err(e)},o)};
g.watchPosition=(ok,err,o)=>{window.__geo.push('watch '+JSON.stringify(o));return wp(p=>{ok&&ok(p)},e=>{window.__geo.push('watch err '+e.code+' '+e.message);err&&err(e)},o)};return 1})()

